CREATE TABLE extension_install_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES owners(id),install_id uuid NOT NULL REFERENCES extension_installs(id) DEFERRABLE,operation_id uuid NOT NULL,request_hash text NOT NULL,remote_target text NOT NULL,state text NOT NULL DEFAULT 'prepared' CHECK(state IN ('prepared','submitted','unknown','cancelled','completed','failed')),receipt jsonb,late boolean NOT NULL DEFAULT false,UNIQUE(owner_id,operation_id));
